<?php
namespace App\Http\Controllers;
use App\Services\WorkshopService;
use App\Support\StockTransactions;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;

class WorkshopController extends Controller {
 public function __construct(){$this->middleware('auth');$this->middleware(function($request,$next){abort_unless($request->user()->active && $request->user()->hasAccess('workshop'),403);return $next($request);});}
 public function index(Request $request){
  $data=$request->validate(['view'=>['nullable',Rule::in(['dashboard','ledgers','stock','fundis'])],'hub_id'=>'nullable|integer|exists:hubs,id','fundi_id'=>'nullable|integer|exists:workshop_fundis,id','q'=>'nullable|string|max:100','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d'.($request->filled('from')?'|after_or_equal:from':'')]);
  $view=$data['view']??'dashboard';$hubs=DB::table('hubs')->where('is_active',true)->orderBy('name')->get();$hubId=$request->filled('hub_id')?(int)$request->hub_id:null;
  $fundis=DB::table('workshop_fundis as f')->leftJoinSub(DB::table('workshop_ledger')->select('fundi_id',DB::raw("SUM(amount) as balance, SUM(CASE WHEN type='earning' THEN amount ELSE 0 END) as earned, SUM(CASE WHEN type='advance' THEN -amount ELSE 0 END) as advanced, SUM(CASE WHEN type='payout' THEN -amount ELSE 0 END) as paid"))->groupBy('fundi_id'),'l','l.fundi_id','=','f.id')->select('f.*',DB::raw('COALESCE(l.balance,0) as balance'),DB::raw('COALESCE(l.earned,0) as earned'),DB::raw('COALESCE(l.advanced,0) as advanced'),DB::raw('COALESCE(l.paid,0) as paid'))->orderByDesc('f.is_active')->orderBy('f.name')->get();
  $fundiId=$request->filled('fundi_id')?(int)$request->fundi_id:($fundis->first()->id??null);$fundi=$fundis->firstWhere('id',$fundiId);
  $production=$view==='dashboard'?(DB::table('workshop_production as p')->join('hubs as h','h.id','=','p.hub_id')->select('p.*','h.name as hub_name')->when($hubId,fn($q)=>$q->where('p.hub_id',$hubId))->orderByDesc('p.id')->paginate(10,['*'],'production_page')->withQueryString()):collect();
  $earnings=$view==='dashboard'?(int)DB::table('workshop_production')->when($hubId,fn($q)=>$q->where('hub_id',$hubId))->sum('amount'):0;
  $advances=$view==='dashboard'?(int)DB::table('workshop_payments')->where('type','advance')->sum('amount'):0;$payouts=$view==='dashboard'?(int)DB::table('workshop_payments')->where('type','payout')->sum('amount'):0;
  $payable=(int)$fundis->sum(fn($f)=>max(0,(int)$f->balance));$ahead=(int)$fundis->sum(fn($f)=>max(0,-(int)$f->balance));
  $ledgerQuery=DB::table('workshop_ledger')->where('fundi_id',$fundiId??0)->select('workshop_ledger.*',DB::raw('SUM(amount) OVER (ORDER BY entry_date,id ROWS UNBOUNDED PRECEDING) as running_balance'));
  $ledger=$view==='ledgers'?(DB::query()->fromSub($ledgerQuery,'l')->leftJoin('workshop_production as p','p.id','=','l.production_id')->select('l.*','p.quantity','p.rate','p.product_name','p.stage')->when($request->filled('from'),fn($q)=>$q->where('l.entry_date','>=',$request->from))->when($request->filled('to'),fn($q)=>$q->where('l.entry_date','<=',$request->to))->orderBy('l.entry_date')->orderBy('l.id')->paginate(10,['*'],'ledger_page')->withQueryString()):collect();
  $broughtForward=$request->filled('from')?(int)DB::table('workshop_ledger')->where('fundi_id',$fundiId??0)->where('entry_date','<',$request->from)->sum('amount'):0;
  $stockSearch=trim($data['q']??'');
  $componentQuery=DB::table('workshop_component_stock as s')->join('workshop_components as c','c.id','=','s.component_id')->join('products as p','p.id','=','c.product_id')->join('hubs as h','h.id','=','s.hub_id')->select('s.quantity','c.kind','p.product_name','h.name as hub_name','h.id as hub_id')->when($hubId,fn($q)=>$q->where('s.hub_id',$hubId));
  $finishedQuery=DB::table('hub_stock as s')->join('products as p','p.id','=','s.product_id')->join('hubs as h','h.id','=','s.hub_id')->select('s.quantity',DB::raw("'finished' as kind"),'p.product_name','h.name as hub_name','h.id as hub_id')->when($hubId,fn($q)=>$q->where('s.hub_id',$hubId));
  $inventory=$view==='stock'?DB::query()->fromSub((clone $componentQuery)->unionAll(clone $finishedQuery),'inventory')->when($stockSearch!=='',fn($q)=>$q->where('product_name','like','%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$stockSearch).'%'))->orderBy('product_name')->orderBy('hub_name')->orderBy('kind')->paginate(50,['*'],'stock_page')->withQueryString():collect();
  $shoeProducts=DB::table('workshop_components')->select('product_id')->union(DB::table('workshop_production')->where('stage','assembly')->select('product_id'));
  $finishedShoes=in_array($view,['dashboard','stock'])?(int)(clone $finishedQuery)->whereIn('s.product_id',$shoeProducts)->sum('s.quantity'):0;
  $shoeStock=$view==='stock'?(clone $finishedQuery)->whereIn('s.product_id',$shoeProducts)->when($stockSearch!=='',fn($q)=>$q->where('p.product_name','like','%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$stockSearch).'%'))->select('p.product_name',DB::raw('SUM(s.quantity) as quantity'))->groupBy('p.id','p.product_name')->orderBy('p.product_name')->paginate(12,['*'],'shoes_page')->withQueryString():collect();
  $upperPairs=in_array($view,['dashboard','stock'])?(int)(clone $componentQuery)->where('c.kind','uppers')->sum('s.quantity'):0;
  $outputTotals=$view==='dashboard'?DB::table('workshop_production')->when($hubId,fn($q)=>$q->where('hub_id',$hubId))->select('stage',DB::raw('SUM(quantity) as quantity'))->groupBy('stage')->pluck('quantity','stage'):collect();
  $products=DB::table('products')->orderBy('product_name')->get(['id','product_name as name','product_code as code','brand']);
  $upperProducts=DB::table('workshop_components as c')->join('products as p','p.id','=','c.product_id')->where('c.kind','uppers')->orderBy('p.product_name')->get(['p.id','p.product_name as name','p.product_code as code','p.brand'])->map(fn($p)=>['id'=>$p->id,'name'=>'Upper · '.$p->name,'code'=>$p->code,'brand'=>$p->brand]);
  $balances=collect();
  return view('workshop.index',compact('view','hubs','hubId','fundis','fundiId','fundi','production','earnings','advances','payouts','payable','ahead','ledger','broughtForward','inventory','stockSearch','shoeStock','finishedShoes','upperPairs','outputTotals','products','upperProducts','balances'));
 }
 public function availability(Request $request){$data=$request->validate(['hub_id'=>'required|integer|exists:hubs,id','product_id'=>'required|integer|exists:products,id']);$quantities=DB::table('workshop_component_stock as s')->join('workshop_components as c','c.id','=','s.component_id')->where('s.hub_id',$data['hub_id'])->where('c.product_id',$data['product_id'])->pluck('s.quantity','c.kind');$allUppers=(int)DB::table('workshop_component_stock as s')->join('workshop_components as c','c.id','=','s.component_id')->where('s.hub_id',$data['hub_id'])->where('c.kind','uppers')->sum('s.quantity');return response()->json(['all_uppers'=>$allUppers,'uppers'=>(int)($quantities['uppers']??0),'soles'=>(int)($quantities['soles']??0),'finished'=>(int)(DB::table('hub_stock')->where('hub_id',$data['hub_id'])->where('product_id',$data['product_id'])->value('quantity')??0)])->header('Cache-Control','private, no-store');}
 public function fundi(Request $request,?int $id=null){
  $data=$request->validate(['name'=>'required|string|max:100','phone'=>'nullable|string|max:30','skills'=>'required|array|min:1','skills.*'=>['distinct',Rule::in(array_keys(WorkshopService::STAGES))],'tailor_rate'=>'required|regex:/^\d{1,8}(\.\d{1,2})?$/','uppers_rate'=>'required|regex:/^\d{1,8}(\.\d{1,2})?$/','assembly_rate'=>'required|regex:/^\d{1,8}(\.\d{1,2})?$/','opening'=>'nullable|regex:/^-?\d{1,8}(\.\d{1,2})?$/','request_key'=>'required|uuid','is_active'=>'nullable|boolean','tailoring_rates'=>'nullable|array:'.implode(',',array_keys(WorkshopService::GARMENTS)),'tailoring_rates.*'=>'nullable|regex:/^\d{1,8}(\.\d{1,2})?$/']);
  $tailoringRates=[];foreach(($data['tailoring_rates']??[]) as $key=>$value){if($value===null || $value==='')continue;$cents=WorkshopService::money((string)$value);if($cents<=0)throw ValidationException::withMessages(['tailoring_rates.'.$key=>'Enter a positive garment rate or leave it blank.']);$tailoringRates[$key]=$cents;}
  $rates=[];foreach(WorkshopService::STAGES as $stage=>$label){$rates[$stage.'_rate']=WorkshopService::money((string)$data[$stage.'_rate']);if(in_array($stage,$data['skills']) && $rates[$stage.'_rate']<=0 && !($stage==='tailor' && $tailoringRates))throw ValidationException::withMessages([$stage.'_rate'=>'Enter a positive rate for '.$label.'.']);}
  try{StockTransactions::run(function()use($request,$id,$data,$rates,$tailoringRates){
   $values=['name'=>trim($data['name']),'phone'=>$data['phone']??null,'skills'=>json_encode(array_values(array_unique($data['skills']))),'tailoring_rates'=>json_encode($tailoringRates?:new \stdClass()),'is_active'=>$request->boolean('is_active'),'updated_at'=>now()]+$rates;
   $opening=(string)($data['opening']??'0');$openingAmount=WorkshopService::money(ltrim($opening,'-'))*(str_starts_with($opening,'-')?-1:1);
   $hash=hash('sha256',json_encode([$request->user()->id,$id,array_diff_key($values,['updated_at'=>true]),$id?null:$openingAmount]));
   $prior=DB::table('workshop_fundi_changes')->where('request_key',$data['request_key'])->first();if($prior){abort_unless(hash_equals($prior->request_hash,$hash),409);return;}
   $before=null;
   if($id){$f=DB::table('workshop_fundis')->where('id',$id)->lockForUpdate()->first();abort_unless($f,404);if(!$values['is_active'] && (int)DB::table('workshop_ledger')->where('fundi_id',$id)->sum('amount')!==0)throw ValidationException::withMessages(['fundi'=>'Settle the balance before archiving this fundi.']);$before=json_encode($f);DB::table('workshop_fundis')->where('id',$id)->update($values);}
   else{$id=DB::table('workshop_fundis')->insertGetId($values+['request_key'=>$data['request_key'],'request_hash'=>$hash,'created_at'=>now()]);$amount=$openingAmount;if($amount)DB::table('workshop_ledger')->insert(['fundi_id'=>$id,'entry_date'=>now('Africa/Nairobi')->toDateString(),'type'=>'opening','amount'=>$amount,'description'=>'Opening balance recorded when fundi was added','actor_id'=>$request->user()->id,'actor_name'=>$request->user()->name,'created_at'=>now()]);}
   DB::table('workshop_fundi_changes')->insert(['fundi_id'=>$id,'before_values'=>$before,'after_values'=>json_encode($values),'actor_id'=>$request->user()->id,'actor_name'=>$request->user()->name,'request_key'=>$data['request_key'],'request_hash'=>$hash,'created_at'=>now()]);
  });}catch(\Illuminate\Database\QueryException $error){if((int)($error->errorInfo[1]??0)===1062)abort(409,'This fundi change was already submitted. Refresh and retry.');throw $error;}return redirect()->route('workshop.index',['view'=>'fundis'])->with('success','Fundi saved. Historical earnings keep their original rates.');
 }
 public function production(Request $request,WorkshopService $service){$data=$request->validate(['fundi_id'=>'required|integer|exists:workshop_fundis,id','hub_id'=>'required|integer|exists:hubs,id','product_id'=>'required|integer|exists:products,id','stage'=>['required',Rule::in(array_keys(WorkshopService::STAGES))],'garment_type'=>['nullable',Rule::in(array_keys(WorkshopService::GARMENTS))],'quantity'=>'required|integer|min:1|max:999999','work_date'=>'required|date_format:Y-m-d','request_key'=>'required|uuid']);$id=$service->production($request->user(),$data);return redirect()->route('workshop.index',['hub_id'=>$data['hub_id']])->with('success','Production #'.$id.' saved. Stock and earnings updated together.');}
 public function payment(Request $request,WorkshopService $service){$data=$request->validate(['fundi_id'=>'required|integer|exists:workshop_fundis,id','type'=>['required',Rule::in(['advance','payout'])],'amount'=>'required|regex:/^\d{1,8}(\.\d{1,2})?$/','payment_date'=>'required|date_format:Y-m-d','method'=>'required|string|max:50','reference'=>'nullable|string|max:100','request_key'=>'required|uuid']);$service->payment($request->user(),$data);return redirect()->route('workshop.index',['view'=>'ledgers','fundi_id'=>$data['fundi_id']])->with('success','Payment recorded. This records money already paid; it does not transfer money.');}
 public function components(Request $request,WorkshopService $service){$data=$request->validate(['hub_id'=>'required|integer|exists:hubs,id','product_id'=>'required|integer|exists:products,id','kind'=>['required',Rule::in(['uppers','soles'])],'quantity'=>'required|integer|min:1|max:999999','note'=>'required|string|max:500','request_key'=>'required|uuid']);$service->components($request->user(),$data);return redirect()->route('workshop.index',['view'=>'stock','hub_id'=>$data['hub_id']])->with('success','Component stock received. No fundi earnings were created.');}
}
